with lines as (select c.id, c.customer_id, c.created_at, c.coupon_codes, entry.qty, entry.price from carts c lateral view explode(c.items) x as entry) select *, round(price / sum(price) over (partition by customer_id), 4) as price_share, avg(price) over (partition by customer_id order by cast(created_at as bigint) range between 1800 preceding and current row) as price_avg_30m, dense_rank() over (partition by customer_id order by qty desc) as qty_dense_rank from lines
